def count(l, by_prefix, square):
    k = len(square)
    if k == l:
        return 1
    prefix = "".join(square[i][k] for i in range(k))
    total = 0
    for w in by_prefix.get(prefix, []):
        square.append(w)
        total += count(l, by_prefix, square)
        square.pop()
    return total

